// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public { 
        deployer = address(this);
        c = new C(); 
    }

    function testFuzz_property(address adr, bytes memory data, uint256 value) public {
        // Bound value to a reasonable amount
        value = bound(value, 0, 1 ether);

        // Record owner before call
        address ownerBefore = c.Owner();

        // Drive the contract through Command
        c.Command(adr, data);

        // Assert that owner remains the deployer (the original caller of new C())
        assertTrue(c.Owner() == deployer);
    }
}

